import type { Lesson } from '../types';

// Shared lessons are technology-neutral where possible. Project code is evidence, not the definition.
export const concepts: Lesson[] = [
  {id:'processes',title:'Processes, threads & the GIL',level:0,group:'OS foundations',summary:'One application process can coordinate many OS threads and child processes.',intuition:'A process is a workshop with its own memory. Threads are workers sharing that workshop; child processes are separate workshops.',technical:'A process owns an address space and OS resources. Threads share that address space but have independent stacks/scheduling state. In CPython, the GIL normally permits only one thread at a time to execute Python bytecode in an interpreter; blocking I/O and native code may release it.',cs:'You studied OS process scheduling. Here, asyncio tasks share one process, ThreadPoolExecutor runs OS threads in that process, and FFmpeg/Deno can run as child processes. Network waiting differs from CPU parallelism.',location:'bot/services/downloader.py · DownloadManager.__init__; yt-dlp launches media tools as subprocesses.',snippet:'ThreadPoolExecutor(max_workers=self.max_concurrent + 2, thread_name_prefix="yt-dl")',why:'yt-dlp APIs are blocking, so they must not stall the asyncio event loop. Threads suit mostly network-bound work; media processing already delegates native work to child tools.',without:'One synchronous extraction could stop the event loop from handling progress, cancellation requests and unrelated chats.',alternatives:'Async-native downloader; ProcessPoolExecutor; dedicated worker service. Processes help CPU-bound Python but add startup, memory and IPC costs; they are not inherently faster.',choice:'Keep the event loop for coordination, thread pools for blocking libraries and subprocesses for FFmpeg/Deno. **[C]** Production has two shared vCPUs and about 952 MiB RAM in the 2026-10-03 snapshot; **[M]** the 24-hour run showed low average CPU busy, so extra Python processes lacked evidence.',interview:'“I use asyncio for many concurrent network-facing handlers, and move blocking yt-dlp calls to a bounded thread pool. Threads do not make Python CPU code parallel under the GIL, but downloads spend much time waiting on sockets; FFmpeg already runs as a child process.”',followup:'If a thread await times out, what is still running, and how would you impose a hard deadline?',resource:'CPU, memory, network',protection:'Bounded worker pool, DownloadQueue admission, systemd cgroup',failure:'Thread work can outlive a cancelled await; child processes may need explicit termination.',scale:'Measure CPU-bound Python time before considering processes; first distinguish it from network wait, native code and steal.'},
  {id:'asyncio',title:'Asyncio & the event loop',level:2,group:'Concurrency',summary:'Cooperative concurrency lets one thread advance many tasks while they wait.',intuition:'One coordinator tends several conversations. When one is waiting for the network, it moves to another ready conversation.',technical:'An asyncio event loop schedules coroutines at suspension points. An `await` yields control; code that blocks synchronously prevents the loop from scheduling other tasks.',cs:'This resembles an OS scheduler but is cooperative in user space: tasks must yield. Async concurrency can overlap I/O but does not itself create CPU parallelism.',location:'bot/main.py · PTB application; bot/handlers/download.py · async request handlers.',snippet:'await asyncio.wait_for(asyncio.shield(wrapped), timeout=timeout)',why:'Telegram handlers wait on remote services and need to keep responding to progress, cancellation and other users.',without:'Blocking calls on the loop delay every task, making heartbeats and callbacks appear hung.',alternatives:'One thread per request; synchronous server; async-native integrations. Threads cost stacks/context; sync serializes waits.',choice:'Use asyncio for orchestration and offload blocking calls. **[C]** PTB concurrent updates are enabled; metadata and downloads use separate executors.',interview:'“Asyncio gives the bot concurrency for I/O waits on one event loop. I keep the loop nonblocking by moving synchronous extraction to executors. It is concurrency, not CPU parallelism.”',followup:'How can you tell event-loop starvation from a slow external HTTP dependency?',resource:'CPU mostly during coordination; sockets while waiting',protection:'Dedicated executors, timeouts, event-loop heartbeat',failure:'One blocking call can stall heartbeat, update processing and cancellation together.',scale:'More tasks help only while they are waiting; admission limits still protect memory and external APIs.'},
  {id:'threads',title:'Threads & ThreadPoolExecutor',level:2,group:'Concurrency',summary:'A bounded pool reuses OS threads for blocking functions.',intuition:'Instead of creating a new worker for every request, keep a fixed crew and let them take jobs.',technical:'A thread pool submits callables to a bounded number of worker threads. `run_in_executor` returns an awaitable, but cancelling that awaitable does not forcibly stop a callable already running.',cs:'Threads are OS-scheduled execution contexts sharing process memory. Python locks/GIL affect Python-bytecode parallelism; blocking network and native libraries can release the GIL.',location:'bot/services/downloader.py · DownloadManager.__init__; `run_in_executor` call sites.',snippet:'self._meta_executor = ThreadPoolExecutor(max_workers=4, thread_name_prefix="yt-meta")',why:'yt-dlp and some clients expose synchronous operations; separate pools keep metadata responsive when downloads are busy.',without:'Unbounded thread creation could use memory and amplify upstream load; a shared saturated pool could cause unrelated work to time out.',alternatives:'Async-native clients, one thread per job, process pool, external workers.',choice:'Separate bounded download, metadata and search pools. **[C]** The current configuration derives download workers from concurrency; metadata has four workers and search three.',interview:'“The thread pool isolates blocking libraries without blocking the event loop, and bounds concurrent calls. I use separate pools where contention between slow downloads and short metadata work would cause head-of-line blocking.”',followup:'How should shutdown handle a worker that ignores cooperative cancellation?',resource:'CPU, thread stacks/RAM, network',protection:'Fixed max_workers, DownloadQueue, task deadlines and systemd cgroup',failure:'A stuck callable occupies a worker after its asyncio caller times out.',scale:'If threads are saturated, identify whether callers wait on network, GIL-bound CPU or a slow dependency before raising limits.'},
  {id:'process-pool',title:'Why not ProcessPoolExecutor?',level:2,group:'Concurrency',summary:'A process pool enables parallel Python execution at a higher isolation and memory cost.',intuition:'A second workshop can work at the same time, but it needs its own space and a way to receive the job.',technical:'Processes have separate address spaces. A process pool serializes work/results (usually IPC) and bypasses the CPython GIL between processes, at the expense of memory, startup and coordination.',cs:'OS process isolation is stronger than threads. It is useful for CPU-bound Python, but subprocess tools such as FFmpeg already do CPU work outside the interpreter.',location:'No ProcessPoolExecutor exists in v1. Download workers are in bot/services/downloader.py; FFmpeg is invoked by yt-dlp.',snippet:'# Deliberately no ProcessPoolExecutor in v1.',why:'There is no measured Python CPU hotspot. Most downloader time is external network and subprocess work.',without:'Adding a process pool without need adds memory/process lifecycle costs in a 952 MiB VM.',alternatives:'ThreadPoolExecutor, explicit subprocess, increase VM size, optimized algorithm.',choice:'Choose the least complex execution model that matches the bottleneck. **[M]** Historical mean CPU busy was low; variable steal confounds the before/after comparison. **Not measured:** CPU time per job split by Python vs child process.',interview:'“I would use a process pool only if profiling identified CPU-bound Python constrained by the GIL. Here the expensive media tools are child processes already and downloads are I/O-heavy, so a process pool would add memory and IPC without solving a measured bottleneck.”',followup:'How would you prove Python CPU is the bottleneck rather than FFmpeg or CPU steal?',resource:'CPU and duplicated memory',protection:'Do not create processes without profiling; keep cgroup limits',failure:'Forking or serializing large state can increase memory and complicate cancellation/shutdown.',scale:'Revisit with profiles showing GIL contention and enough memory headroom.'},
  {id:'tcp-http',title:'TCP, HTTP & client/server',level:0,group:'Networking foundations',summary:'A bot message crosses multiple clients, servers and network failure boundaries.',intuition:'A request is a conversation over a connection; a timeout means you stopped waiting, not necessarily that the other side did nothing.',technical:'TCP provides ordered byte transport while HTTP defines request/response semantics above it. Telegram Bot API calls are remote HTTP operations; yt-dlp also contacts third-party services.',cs:'Your CN knowledge of sockets, handshakes, retransmits and DNS explains why remote latency and failures are variable. Application timeouts bound waiting but do not undo remote effects.',location:'bot/handlers/download.py · Telegram send calls; `requirements.txt` · PTB/httpx/curl_cffi clients.',snippet:'await context.bot.send_video(..., video=InputFile(f, read_file_handle=False))',why:'Every request depends on Telegram and media platforms outside the VM.',without:'Assuming the network is reliable creates indefinite waits, duplicate sends and opaque failures.',alternatives:'Retries, circuit breakers, alternate egress, local Bot API server; each addresses different failure or limit.',choice:'Use bounded timeouts and retries only for understood transient failures. Media source access and Telegram delivery are separate dependencies.',interview:'“The bot is a client of both Telegram and media sites. HTTP timeouts bound local waiting, but a timeout after upload can leave the result ambiguous because Telegram may already have received the file.”',followup:'How do retries risk duplicate side effects when a response is lost?',resource:'Network bandwidth and connection slots',protection:'HTTP timeouts, retry classification, rate limits, health checks',failure:'DNS, routing, source throttling, Telegram flood control, reset connections and ambiguous completion.',scale:'At higher load, measure per-dependency latency, error rate, bandwidth and rate limits separately.'},
  {id:'queue',title:'Queues, fairness & workers',level:3,group:'Scheduling',summary:'A queue allocates scarce worker capacity fairly; active slots are bounded, but the waiting list has no hard length cap.',intuition:'Requests wait in an organized line rather than all consuming CPU, memory and network at once.',technical:'A producer-consumer queue decouples admission from processing. A scheduler selects eligible jobs; fairness policies reduce starvation but may trade strict FIFO ordering for priority. A bounded worker count is different from a bounded waiting queue.',cs:'OS schedulers allocate CPU time to runnable tasks; an application queue allocates job slots before work begins. These are different layers of scheduling.',location:'bot/services/dl_queue.py · DownloadQueue; `bot/handlers/download.py` · job admission.',snippet:'class DownloadQueue:\n    def __init__(self, slots: int, per_user: int = PER_USER): ...',why:'Downloads have variable duration and consume temporary disk, external bandwidth and CPU.',without:'Starting every accepted job can oversubscribe the host; an uncapped wait list can still grow under sustained overload.',alternatives:'FIFO only, priority queue, per-user round robin, bounded rejection policy, broker-backed durable queue.',choice:'A fair in-memory queue fits one process and current traffic. **[C]** Production global download concurrency is 3 and per-user active limit is 2. The waiting list has no configured maximum.',interview:'“The queue schedules active work and gives fairness across users. Worker slots are bounded; the wait list itself is in-memory and not hard-capped, so I would measure its depth and add explicit admission/rejection if sustained overload appeared.”',followup:'What policy prevents premium priority from starving normal users indefinitely?',resource:'CPU, RAM, disk, network, external service quota',protection:'Global slots, per-user active limits, rate limit, UploadGate downstream',failure:'Queue growth can be unbounded wait or memory use if accepted work exceeds service capacity.',scale:'Measure queue depth and wait time; a durable queue solves restart/cross-worker needs, while an admission cap addresses overload growth.'},
  {id:'backpressure',title:'Admission control & backpressure',level:3,group:'Scheduling',summary:'Resource gates limit active work, but true backpressure also needs a policy for the waiting backlog.',intuition:'A narrow pipe should not be fed at a rate that floods the tank behind it.',technical:'Backpressure propagates downstream capacity constraints toward producers through bounded queues, admission control or flow control. A concurrency limit alone may leave an unbounded backlog.',cs:'This is producer-consumer synchronization and resource reservation, not merely a queue data structure.',location:'bot/services/dl_queue.py and bot/services/upload_gate.py.',snippet:'async with upload_gate.reserve(file_size, cancel_event):\n    await send_with_retries(...)',why:'Download completion can outpace Telegram upload capacity; download and upload consume different resources.',without:'Completed files accumulate and may hold scarce download slots while waiting to send; the download queue wait list can also grow.',alternatives:'Unbounded wait, reject requests, durable jobs, throttle producers, explicit queue cap.',choice:'Bound active downloads and uploads separately; release download capacity before waiting for upload capacity. **[C]** UploadGate caps two active uploads and a 100 MiB budget by default. The DownloadQueue wait list is not length-bounded, so this is not complete upstream backpressure.',interview:'“The bot has active-work limits and a separate upload gate, preventing upload waits from holding download slots. The waiting queue itself is not hard-bounded, so I would add rejection or durable admission if measurements showed backlog growth.”',followup:'At which boundary should overload be rejected, and what should the user see?',resource:'Memory, disk, bandwidth and service slots',protection:'Worker limits, UploadGate FIFO/byte budget, rate limits; wait-list cap is a future trigger',failure:'Without a backlog policy, queue and temporary files can grow until latency or resource exhaustion.',scale:'Track queue wait/depth and temp disk; define bounded admission if arrivals persist above service capacity.'},
  {id:'semaphore',title:'Semaphores & resource tokens',level:3,group:'Scheduling',summary:'A semaphore represents a limited number of simultaneous permits.',intuition:'A room has three keys; only three people can enter until someone returns a key.',technical:'A counting semaphore decrements on acquisition and increments on release. It limits concurrent critical sections but does not itself provide fairness, byte accounting or durable queueing.',cs:'This is synchronization familiar from OS producer-consumer problems. A permit is a logical token, not a CPU core.',location:'bot/services/downloader.py · DownloadManager._sem; UploadGate implements richer admission; bot/handlers/inline.py also has stage-specific semaphores.',snippet:'self._sem = asyncio.Semaphore(self.max_concurrent)',why:'Cap simultaneous downloads or limited inline stages.',without:'Unbounded concurrent jobs can amplify resource use and external requests.',alternatives:'Worker queue, bounded channel, token bucket, cgroup CPU quota.',choice:'Use resource-specific admission where measured or required by invariants. A semaphore cannot account for varying file sizes, so UploadGate also tracks bytes.',interview:'“A semaphore caps in-flight operations. It does not make the operation faster or guarantee FIFO fairness. For uploads, we need both a slot and a byte budget, which is why the gate is more than a plain semaphore.”',followup:'Can a semaphore bound total queued work? What extra policy would you need?',resource:'The resource guarded by its permit',protection:'Acquire/release context, cancellation cleanup, global admission',failure:'Leaked permits or cancellation races can deadlock capacity.',scale:'Add a new semaphore only after identifying the resource and proving the existing global bounds do not protect it.'},
  {id:'rate-limiting',title:'Rate limiting',level:3,group:'Scheduling',summary:'Limit how often a user may start work over time.',intuition:'Concurrency says how many are happening now; rate says how many can start over a period.',technical:'A sliding-window counter, fixed window, token bucket or leaky bucket enforces a temporal request budget. Rate limiting protects both the service and upstream APIs.',cs:'Related to traffic shaping in networking, but policy is applied per identity at the application layer.',location:'bot/services/rate_limit.py; bot/services/user_prefs.py · premium multiplier.',snippet:'RATE_LIMIT_PER_HOUR = int(os.getenv("RATE_LIMIT_PER_HOUR", "30"))',why:'Prevent abuse and bound repeated downloads independently of worker slots.',without:'A single user can continuously refill the queue as workers finish.',alternatives:'Fixed window, token bucket, global upstream quota, Telegram-side controls.',choice:'A process-local per-user hourly limit is simple for one bot process. **[C]** admins bypass; production snapshot used 40/hour. It is not distributed across replicas.',interview:'“Rate limiting caps arrivals over time; the download queue caps concurrent work. Both matter: a low concurrency cap alone still lets a client monopolize the queue.”',followup:'What breaks if the bot runs two replicas with independent in-memory rate limiters?',resource:'CPU, network, third-party quota',protection:'Per-user local rate limiter plus global queue',failure:'State resets on restart and would diverge across multiple processes.',scale:'Use shared rate-limit state only when multiple replicas or abuse patterns require cross-process enforcement.'},
  {id:'singleflight-cache',title:'Single-flight vs cache',level:4,group:'Deduplication',summary:'Cache answers repeated past work; single-flight joins work that is happening now.',intuition:'Cache asks “have we computed it?” Single-flight asks “is someone computing it right now?”',technical:'A cache stores completed values with eviction/TTL. Single-flight tracks in-progress calls by key and shares a promise/future among concurrent callers. It is request coalescing, not transaction isolation.',cs:'A cache is a data-structure/lifetime problem. Transaction isolation controls concurrent database transactions and visibility. These concepts are distinct.',location:'bot/services/downloader.py · `_META_CACHE`, `DownloadManager._meta_inflight`, `analyze` path.',snippet:'flight = self._meta_inflight.get(key)\nif flight is None:\n    self._meta_inflight[key] = flight = _MetaFlight(...)',why:'Several users may request metadata for the same URL at once; duplicate extraction can consume all four metadata workers.',without:'Seven simultaneous cache misses can launch seven extractions even if the cache is populated after the first completes.',alternatives:'Cache only; distributed lock; no deduplication.',choice:'Use bounded TTL cache for later repeats and single-flight for overlapping misses. **[C]** metadata cache is capped at 64 and 180 seconds; the in-flight map shares one extraction per key.',interview:'“The cache handles completed work, while single-flight coalesces concurrent misses. Seven callers for one URL should create one extraction and six waiters; this is not a database transaction guarantee.”',followup:'How should a failed leader communicate its exception and cleanup the in-flight key?',resource:'Metadata worker slots, upstream network',protection:'Bounded cache, lock-protected in-flight map, timeout handling',failure:'Incorrect cleanup can strand waiters; key normalization mistakes can duplicate work.',scale:'A process-local implementation stops coalescing across processes; shared coordination is only justified if multiple workers need it.'},
  {id:'streaming',title:'Streaming, buffers & file handles',level:5,group:'Memory and I/O',summary:'Stream chunks from disk to the network instead of materializing an entire media file in Python.',intuition:'Carry a box one small parcel at a time instead of lifting the whole warehouse into memory.',technical:'Streaming performs incremental reads and writes through bounded buffers. A file handle is a reference to an open file descriptor; it does not imply the file bytes are resident in Python heap.',cs:'OS file I/O uses page cache, so streaming does not mean zero memory. It avoids a large Python `bytes` allocation; the kernel may cache file pages and reclaim them under pressure.',location:'bot/handlers/download.py · `_send_media_once`, video/audio/photo/document sends.',snippet:'InputFile(f, filename=filename, read_file_handle=False)',why:'Telegram sends may involve a large file up to the app’s 49 MB cap. Loading it all into Python memory creates avoidable anonymous RSS amplification.',without:'Concurrent uploads could each allocate a full media-sized byte string and compete with the small VM memory limit.',alternatives:'Read all bytes; mmap; stream from object storage; upload by Telegram file_id if already cached.',choice:'Keep the download on temporary disk and let the HTTP client read the open file in chunks. **[C]** The call explicitly sets `read_file_handle=False`; **[M]** measurement saw higher average available memory after a bundle of changes, but did not isolate streaming causality.',interview:'“We used to risk holding an entire media file in Python memory during upload. The current InputFile path streams the disk handle. This reduces Python heap amplification, though Linux page cache still uses reclaimable memory.”',followup:'Why can RSS still change when an upload streams from disk?',resource:'Disk reads, network sockets, bounded buffers, page cache',protection:'Streaming InputFile, UploadGate slots and byte budget, 49 MB final limit',failure:'Open file must remain valid and seek/reopen correctly for fallback or retry.',scale:'Measure memory per concurrent upload and disk/network throughput; streaming shifts pressure rather than eliminating it.'},
  {id:'memory-virtual',title:'RSS, virtual memory & page cache',level:6,group:'Linux memory',summary:'A process’s RSS is only one part of system memory pressure.',intuition:'RAM is a shared workspace. Some space is private notes; some is a cache the OS can throw away and rebuild.',technical:'Virtual memory maps addresses to physical pages. RSS counts resident mapped pages; anonymous memory is process-private allocations; page cache holds file-backed pages. `MemAvailable` estimates reclaimable headroom better than simply subtracting used memory.',cs:'You learned demand paging and page tables. A page fault is a mapping event; a major fault requires storage I/O and can affect latency. Major-fault counters are not a direct count of user-visible failures.',location:'Application upload path in `bot/handlers/download.py`; 24-hour host metrics in historical report summarized by `docs/ARCHITECTURE.md`.',snippet:'file handle → bounded read → HTTP client → socket',why:'The VM has about 952 MiB RAM in the verified snapshot, shared with Kuma and supporting processes.',without:'Reading “used RAM” or a process RSS alone can misdiagnose memory pressure; file cache may be reclaimable while anonymous memory is not.',alternatives:'Increase RAM, stream data, reduce concurrency, tune OS reclaim.',choice:'Stream large payloads and monitor available memory, swap activity and PSI together. **[M]** historical available memory averaged 449 MB vs 346 MB baseline in the 24-hour comparison; CPU steal and bundled changes confound cause.',interview:'“RSS tells me how much mapped memory is resident for a process, but host pressure also depends on page cache, reclaimability, other cgroups and swap. I pair it with MemAvailable, PSI and swap-in activity.”',followup:'How can a process have low RSS while the host is under memory pressure?',resource:'Physical RAM, page cache and storage I/O',protection:'Streaming, UploadGate, cgroup MemoryHigh/Max',failure:'Reclaim and major faults can create latency; memory limits can trigger OOM or throttling/reclaim.',scale:'At higher concurrency estimate memory per active stage and verify aggregate cgroup headroom.'},
  {id:'swap-psi',title:'Swap, PSI & zswap',level:7,group:'Linux memory',summary:'Swap occupancy is not the same as active memory distress; pressure stall information measures time lost waiting.',intuition:'A storage closet can contain items without anyone currently searching it. The urgent signal is people waiting on reclaim or swap I/O.',technical:'Swap-out writes anonymous pages to backing storage; swap-in reads them back. PSI reports some/full stall time for CPU, memory and I/O. zswap compresses pages in RAM before they reach swap backing, trading CPU/RAM for less I/O.',cs:'Virtual memory allows inactive pages to leave RAM. Some swap used can be normal; active swap-in bursts plus memory PSI and latency are stronger distress evidence.',location:'No zswap setting in application code. VM experiment summary appears in docs/ARCHITECTURE.md; systemd cgroup limits in deployment.',snippet:'[M] Historical swap-in mean: 22.82 → 10.46 pages/s; zswap remained disabled.',why:'The constrained VM showed residual swap bursts, and Kuma had previously hit its container memory limit.',without:'Blindly disabling swap can remove an OOM safety margin; blindly enabling zswap can add CPU and memory costs without proving benefit.',alternatives:'Disable swap, adjust swappiness, add RAM, change sidecar limits, controlled zswap A/B.',choice:'Swap was kept enabled; swappiness was 10 and zswap disabled in the measured snapshot. **[M]** the 24-hour run showed lower average swap-in/out but did not isolate zswap.',interview:'“A positive swap-used number is not automatically a problem. I care about active swap-in/out, memory PSI, available memory and latency. We kept swap as a safety buffer and deferred zswap because the observational run did not test it.”',followup:'Design a reversible zswap experiment that separates CPU cost from reduced storage I/O.',resource:'RAM, CPU, disk I/O and latency',protection:'Application streaming, cgroup caps and monitoring pressure signals',failure:'Sustained swap-in can cause stalls; zswap can consume memory and CPU.',scale:'Use a controlled A/B only if fresh pressure measurements identify a latency problem.'},
  {id:'cpu-steal',title:'CPU accounting & steal time',level:8,group:'Linux performance',summary:'CPU steal is time your VM was ready to run but the hypervisor scheduled other guests.',intuition:'Your VM is waiting for a turn on the physical processor, even though your own process is runnable.',technical:'Guest CPU accounting partitions time into user, system, idle, iowait, steal and related states. Steal reflects hypervisor-level scheduling delay reported to the guest.',cs:'This extends OS scheduling across virtualization: physical host → hypervisor → guest VM scheduler. Adding guest worker processes cannot reclaim host CPU stolen by another VM.',location:'Host `sar` data summarized in the historical 24-hour report; no app code controls steal.',snippet:'physical host → hypervisor → VM vCPU → process/thread',why:'Production uses two shared vCPUs, where noisy neighbors can vary available execution time.',without:'Attributing a latency change to bot changes when steal changed mistakes correlation for causation.',alternatives:'Dedicated CPU instance, larger VM class, tune app parallelism, wait for contention to pass.',choice:'Treat steal as an external capacity factor. **[M]** mean steal changed 2.63% to 1.98% across historical baseline/trial; that confounds the before/after comparison.',interview:'“CPU steal is runnable guest work delayed by the hypervisor. More worker processes can increase contention but cannot reclaim stolen host time. I would correlate steal with queue wait and per-job latency before changing concurrency.”',followup:'How would you separate application saturation from noisy-neighbor latency?',resource:'Guest CPU availability',protection:'Cgroup CPU quota, bounded concurrency, host metrics',failure:'High steal can raise latency while guest process CPU looks deceptively low.',scale:'If sustained steal violates latency goals, measure a larger/dedicated VM before changing app architecture.'},
  {id:'cgroups-systemd',title:'systemd & cgroups',level:9,group:'Linux operations',summary:'systemd supervises process lifecycle; cgroups account for and constrain resource groups.',intuition:'systemd is the service manager; a cgroup is a labeled resource envelope for the service and its children.',technical:'systemd starts/stops services and applies policy. Linux cgroups group processes and can control memory, CPU, tasks and accounting. A cgroup includes child processes such as media tools depending on unit mode.',cs:'OS process management and resource scheduling become production operations: service restart, signals, memory reclaim/limits and CPU quota.',location:'deploy/harden_server.sh; production systemd unit snapshot documented in `docs/OPERATIONS.md`.',snippet:'MemoryHigh=480 MiB · MemoryMax=600 MiB · CPUQuota=1.8 CPU · TasksMax=128',why:'The host has about 952 MiB RAM and shared CPU; bot, Kuma and bgutil must coexist.',without:'An unbounded process tree can exhaust the entire VM or survive process cleanup unexpectedly.',alternatives:'Container limits, supervisor, shell process, bigger VM.',choice:'Use systemd plus cgroups for the host bot and containers for side services. These are isolation and lifecycle tools, not horizontal scaling.',interview:'“Running `python run.py` gives me a process; systemd gives managed lifecycle, logs, restart policy and signal handling. Cgroups bound and account for the service’s resource use, including child processes.”',followup:'What is the behavioral difference between MemoryHigh and MemoryMax during reclaim?',resource:'CPU, memory, process/task count',protection:'cgroup limits, sandbox directives, health monitor',failure:'Too-tight limits cause reclaim, OOM kills or service restart loops.',scale:'Tune from service-level usage and failure evidence; isolate sidecars only when their resource use affects bot objectives.'},
  {id:'containers',title:'VMs, containers & namespaces',level:10,group:'Deployment',summary:'Containers share a host kernel while isolating process views and resource groups.',intuition:'A VM is a separate house with a guest OS; a container is a fenced room that shares the building’s kernel.',technical:'Containers combine namespaces (views of processes, network, mounts, etc.) with cgroups and filesystem/image packaging. They are not full VMs and do not inherently provide capacity or fault isolation equivalent to separate hosts.',cs:'OS namespaces virtualize resource visibility; cgroups limit/account usage. Docker packages images and manages runtime/lifecycle.',location:'docker-compose.yml defines a local bot + bgutil provider; production snapshot has Kuma and bgutil in Docker while bot runs under host systemd.',snippet:'docker-compose.yml: bot and bgutil-provider services',why:'Kuma and bgutil have separate lifecycle/resource boundaries; Compose also offers a portable local topology.',without:'If every process shares one unmanaged lifecycle, updates and resource ownership become harder to reason about.',alternatives:'Run all services on host, containerize the bot too, full VM per component, Kubernetes.',choice:'Use only the isolation/runtime needed. “Put everything in Docker” is packaging, not a scaling strategy.',interview:'“Containers isolate process and filesystem/network views using kernel namespaces and cgroups while sharing the host kernel. In production the bot is systemd-managed on the host and side services are containers; that topology is an operational choice, not evidence of distributed scale.”',followup:'Which failure domains remain shared by two containers on one VM?',resource:'Host CPU/RAM/disk/network and image storage',protection:'container limits, cgroup and systemd boundaries',failure:'Containers still share kernel and host capacity; one VM failure stops all.',scale:'Use multiple hosts only when availability/capacity requirements exceed a single host.'},
  {id:'sqlite-wal',title:'SQLite, transactions & WAL',level:11,group:'Persistence',summary:'SQLite gives this single-node service transactional local history without a database server.',intuition:'A well-organized filing cabinet with a transaction ledger is enough when one office owns the records.',technical:'SQLite is an embedded relational DB. WAL (write-ahead logging) records changes sequentially so readers can often continue against a stable snapshot while a writer appends; checkpoints later merge WAL into the main database.',cs:'DBMS transactions and locking apply directly. WAL improves reader/writer interaction but SQLite still serializes writers; it does not provide shared multi-host storage semantics.',location:'bot/services/history.py · `_connect`, `_SCHEMA`, `_migrate_json`.',snippet:'con.execute("PRAGMA journal_mode=WAL")',why:'History/stats need indexed transactional writes; a server database would add deployment/backup/availability work.',without:'Rewriting entire JSON histories can cause costly parsing and GIL-held work; concurrent file writes are fragile.',alternatives:'JSON file, PostgreSQL, external analytics store.',choice:'SQLite WAL fits one bot process and local workload. **[C]** legacy JSON is migrated/renamed; active queue/session state remains separate and volatile.',interview:'“SQLite WAL lets the bot keep durable local history with transactional indexed writes and concurrent readers. It does not make job execution durable and it is not a multi-node shared database.”',followup:'What happens if a long-lived reader prevents a WAL checkpoint?',resource:'Disk I/O and lock time',protection:'transactions, thread lock and SQLite busy timeout',failure:'WAL growth, busy writes, disk-full errors or a missing WAL alongside the database.',scale:'Consider PostgreSQL when multiple nodes need shared state, write contention or managed HA; not just because traffic sounds large.'},
  {id:'durability-idempotency',title:'Durability, idempotency & ambiguous outcomes',level:12,group:'Failure handling',summary:'A retry after timeout may repeat a side effect that already succeeded remotely.',intuition:'You mailed a package, lost the receipt, and cannot tell if sending again will create a duplicate.',technical:'Durability means state survives process failure. Idempotency means repeating an operation with the same key has the same effect as doing it once. Exactly-once effects across remote systems generally require cooperation, durable deduplication or reconciliation.',cs:'DBMS commit acknowledgments have the same ambiguity: the server may commit then the connection drops before the client sees success.',location:'bot/services/inflight.py is a bounded restart notification registry, not a durable work queue; Telegram send path in bot/handlers/download.py.',snippet:'“request timed out” does not imply “Telegram received nothing.”',why:'Remote Telegram upload and local job state cannot commit atomically together.',without:'Blind retries can duplicate delivery or repeat expensive downloads.',alternatives:'At-most-once (risk loss), at-least-once + dedupe, idempotency token if API supports it, reconciliation.',choice:'v1 has bounded retries and best-effort interruption markers; it does not promise exactly-once delivery or resumable jobs.',interview:'“If Telegram receives the file but our HTTP request times out, the outcome is ambiguous. Retrying could duplicate the message. The bot cannot atomically commit its local state and Telegram’s external side effect, so I would describe its delivery semantics honestly.”',followup:'What durable state and API support would you need to make retries safe?',resource:'Remote request cost, local storage, duplicate user-visible effects',protection:'retry classification, bounded attempts, interruption notifications',failure:'Lost response after remote success creates uncertain outcome.',scale:'Add idempotency/durable queue only when duplicate/lost work requirements justify the complexity.'},
  {id:'cancellation-retry',title:'Timeouts, retries & cancellation',level:13,group:'Failure handling',summary:'Timeout bounds waiting; cancellation is a request to stop; neither guarantees a thread stopped.',intuition:'Telling a worker to stop is different from physically taking away its tools.',technical:'Cooperative cancellation sets a flag/event checked at safe points. Python cannot safely force-kill an arbitrary thread. Child processes can be signaled but may need process-group cleanup. Retries should separate transient from permanent errors and use bounded backoff.',cs:'OS signals terminate processes; a Python threading.Event is shared state observed by code. Async task cancellation injects control flow but does not terminate a synchronous callable already running in an executor.',location:'bot/services/jobs.py · threading.Event; bot/utils/deadline.py; bot/handlers/download.py · `_send_media` retries.',snippet:'self.event = threading.Event()',why:'Users need cancellation while sources, media tools and Telegram can stall.',without:'Unbounded work can continue after user cancellation or occupy all pool workers beyond a timeout.',alternatives:'Cooperative flag, subprocess kill, process-isolated worker, hard VM restart.',choice:'Cancel queued work and ask active work to stop cooperatively; bounded deadlines and systemd stop timeout are outer limits. Upload cancellation is limited once send begins.',interview:'“A timeout cancels the coroutine’s wait but not necessarily the executor thread. The downloader checks a threading.Event at cooperative points; stronger hard-kill guarantees would require process isolation and explicit child cleanup.”',followup:'How would you avoid killing a newer job’s child process when cleaning up a cancelled one?',resource:'worker slots, CPU/network, child processes',protection:'threading.Event, deadline checks, queue cancellation, systemd cgroup stop',failure:'Non-cooperative native/network calls outlive callers; retries may overlap abandoned work.',scale:'Use process isolation when stuck-work deadlines are measured and affect SLOs.'},
  {id:'observability',title:'Logs, metrics, health & SRE',level:14,group:'Operations',summary:'Monitoring checks known signals; observability helps explain unknown behavior from telemetry.',intuition:'A smoke alarm tells you something may be wrong; logs, meters and traces help find why.',technical:'Logs are event records; metrics are time-series aggregates; traces connect work across stages. A health check is a bounded probe, not proof all user paths are healthy. SLI measures behavior; SLO is a target; an alert routes actionable risk.',cs:'A system can be “running” while its event loop is hung. Heartbeats test progress, not just process existence.',location:'bot/services/heartbeat.py; scripts/bot_health_server.py; docs/OPERATIONS.md; deployment Kuma monitors.',snippet:'heartbeat.json is written every 30s; health considers service, heartbeat, polling, dependencies and disk.',why:'systemd active state alone misses a stalled event loop, failed polling or broken required dependencies.',without:'A green process status can conceal that users cannot submit or upload jobs.',alternatives:'Process check only, synthetic user journey, tracing backend, full observability stack.',choice:'Local heartbeat + health endpoint + journal + Kuma match a small service. Upload-duration and per-job resource attribution remain gaps.',interview:'“Monitoring answers whether known checks pass; observability helps diagnose behavior we did not anticipate. The heartbeat catches a stuck event loop that systemd active cannot, while a green health endpoint still does not prove every upload works.”',followup:'What SLI would you define for completed user jobs, and how would you avoid counting rejected URLs?',resource:'CPU/disk/network and operator attention',protection:'5s check cache, isolated health service, redacted logs',failure:'Noisy alerts, stale metrics, liveness mistaken for end-to-end success.',scale:'Add per-stage metrics/traces when questions cannot be answered from current logs/counters.'},
  {id:'experiments-percentiles',title:'Experiments & latency percentiles',level:15,group:'Measurement',summary:'A before/after observation is not causal proof; percentiles reveal the tail.',intuition:'Averages can hide the few users who wait a long time; a comparison can change for several reasons at once.',technical:'A p95 is the value at or below which 95% of measured observations fall. Experiments need a hypothesis, controlled variables, adequate sample and treatment of confounders. Small samples make tail percentiles noisy.',cs:'Statistics turn performance claims into testable statements. CPU steal, time-of-day and request mix are confounders.',location:'Historical 24-hour comparison summarized in docs/ARCHITECTURE.md; warm-up timing tests and bot journal events provide distinct populations.',snippet:'[M] warm-up success median/p95: 4.8/34.0 s → 3.9/7.1 s (historical vs trial)',why:'Measure whether resource and warm-up changes helped rather than relying on impressions.',without:'One unusual run or changed CPU steal can be mistaken for an optimization effect.',alternatives:'One-variable A/B, repeated crossover, synthetic load, observational comparison.',choice:'Report metrics with population/time window and causality caveat. User-job sample was too small to demonstrate user-visible latency improvement.',interview:'“I separate measurement from causal attribution. The 24-hour bundle had lower swap and warm-up tails, but CPU steal changed too and user jobs were sparse, so I would call it an association, not proof.”',followup:'How many independent samples make a p99 useful for your latency target?',resource:'Measurement time and data quality',protection:'baseline, matching windows, timestamps, contamination exclusions',failure:'confounding, selection bias, tiny sample, percentile mismatch',scale:'Run controlled experiments for high-cost configuration changes; use percentiles only with adequate sample size.'},
  {id:'little-law',title:'Little’s Law & queueing intuition',level:17,group:'Capacity',summary:'In a stable system, average work in system L equals arrival rate λ times average time W.',intuition:'If three jobs arrive each minute and each stays ten minutes, about thirty jobs are present on average.',technical:'Little’s Law is L = λW for a stable system with consistent boundaries and long-run averages. It does not directly predict burst backlog or per-worker service capacity.',cs:'This connects queues and throughput to response time; it is not a benchmark or a guarantee for transient bursts.',location:'Applies to DownloadQueue and UploadGate; exact production arrivals/day and queue wait were not provided in repository evidence: **Not measured.**',snippet:'L = λ × W',why:'It helps estimate in-flight work from arrivals and time, then reason about concurrency and memory.',without:'Daily average requests can hide a short burst that overwhelms three slots.',alternatives:'Discrete-event simulation, queueing models with service distributions, direct measurement.',choice:'Use Little’s Law for a first-order stable average and simulate bursts separately. Treat every slider output as **[E]** educational math.',interview:'“Little’s Law relates average queue population to arrival rate times total time in the system. It helps sanity-check capacity, but it assumes stable averages and does not explain burst tails by itself.”',followup:'Why can a system become unstable when arrival rate approaches service rate?',resource:'worker slots, queueing delay, memory',protection:'measure arrival/service distributions; bound admission',failure:'Using long-run averages to understate bursts or unstable queue growth.',scale:'Track arrival rate and service time separately; increase capacity only when measured backlog/wait violates objectives.'},
  {id:'capacity',title:'Capacity planning & temporary storage',level:18,group:'Capacity',summary:'Estimate network, disk, memory and throughput from a workload instead of guessing.',intuition:'A download and its upload use separate legs of the trip; a local temp file occupies disk while waiting between them.',technical:'Capacity planning combines arrival rate, job duration, bytes/job, concurrency and resource use. Network Mbps ≈ bytes × 8 / time; temp disk depends on concurrent active file sizes and cleanup lag.',cs:'This is dimensional analysis plus queueing. Keep download and Telegram upload bandwidth separate, and do not substitute averages for peak bursts.',location:'[C] `MAX_FILE_SIZE_MB=49`, `DOWNLOAD_MAX_BYTES=3×` that by default; download concurrency config. **Not measured:** actual bytes/job, jobs/day, upload/download bandwidth and temp occupancy distribution.',snippet:'GB/day ≈ jobs/day × average MB/job ÷ 1024',why:'The VM is small; knowing which resource could bind is more useful than adding generic workers.',without:'A 100× request increase has very different impact depending on media size, processing and upload time.',alternatives:'Measure exact per-job accounting; conservative estimate; reserve disk budget.',choice:'Calculate ranges and label assumptions **[E]**. Do not invent production traffic or average file size.',interview:'“I estimate each resource separately: queue concurrency from service time, bandwidth from bytes over time, and temporary disk from concurrent downloads plus cleanup lag. Then I validate with measured distributions.”',followup:'How does upload duration change the count of open temp files if the download slot is already released?',resource:'network, disk, memory, CPU',protection:'size/time caps, worker and upload bounds, cleanup',failure:'Disk fills, upload becomes bottleneck, arrival rate outruns service rate.',scale:'Add aggregate disk admission when measured concurrent temp files approach free-space headroom.'},
  {id:'bottlenecks',title:'Bottlenecks & utilization',level:19,group:'Performance',summary:'System throughput is limited by the most constrained stage; more concurrency can worsen the bottleneck.',intuition:'A wider entrance does not help if the bridge after it is narrow.',technical:'Utilization is busy fraction of a resource. As a saturated resource approaches full utilization, queueing delay can rise sharply. Concurrency can increase contention, memory use, upstream throttling and context switching.',cs:'Operating systems schedule tasks, but application throughput also depends on network, disk, locks and remote services.',location:'Queue, metadata pool, upload gate, systemd cgroups and external APIs are separate stages.',snippet:'URL → metadata → download → temp disk → upload',why:'Find the resource or stage that limits completed jobs before changing worker count.',without:'Increasing downloads while Telegram upload is saturated creates more files and longer waits.',alternatives:'Optimize hot stage, increase its capacity, shed load, reduce work per request.',choice:'Measure queue wait, stage duration, PSI, disk, bandwidth and API responses. **[M]** low mean CPU does not rule out short burst or external bottlenecks.',interview:'“I look for the constrained stage and its queue. More workers help only if the worker stage is limiting; if disk, upload or upstream limits bind, added concurrency can worsen latency.”',followup:'Which signals distinguish CPU saturation from CPU steal?',resource:'whichever stage is constrained',protection:'bounded queues/gates, cgroups, timeouts and metrics',failure:'Head-of-line blocking, queue growth, resource contention or external throttling.',scale:'Change only the bottleneck proven by telemetry; then remeasure for bottleneck migration.'},
  {id:'system-design',title:'System design from requirements',level:20,group:'System design',summary:'Derive an architecture from functional needs, workload and constraints.',intuition:'Draw boxes only after you know what must work, for whom, and under what load.',technical:'A system design balances functional requirements, latency/availability goals, workload, resource budgets, state semantics, failure handling, and operational complexity.',cs:'This composes OS, networks, databases and algorithms into a system. Capacity estimates inform design; measurements validate it.',location:'The current architecture is a single polling bot with local queue/state, SQLite, temporary disk and external media services.',snippet:'requirements → workload → constraints → bottleneck → design → evidence',why:'Prevent tool-first design and resume-driven infrastructure.',without:'A Kafka/Redis/Kubernetes answer may solve requirements the product does not have while adding operational risk.',alternatives:'Single process, larger VM, separate worker, durable broker, multi-node service.',choice:'Start with current traffic and service needs; make evolution conditional on measured triggers, not arbitrary multipliers.',interview:'“I would first clarify job size, arrival bursts, latency, file-size cap, failure recovery and availability goals. Then I’d estimate resource use and choose the simplest design that meets them, with explicit triggers for evolution.”',followup:'What requirement makes a durable queue necessary even if throughput is low?',resource:'all resource and operational budgets',protection:'explicit requirements, safety limits and failure tests',failure:'Under-specified workloads create wrong assumptions and premature complexity.',scale:'At each scale factor, name what fails first and what measurement proves it.'},
  {id:'scale-triggers',title:'Scale this project without guessing',level:21,group:'System design',summary:'Traffic multipliers are thought experiments; technology choices depend on what breaks.',intuition:'Ten times more asks “which limit hits first?”, not “which framework should we buy?”',technical:'Horizontal scale adds nodes and coordination. It requires shared/durable state, idempotent ownership, storage strategy and network-failure semantics. Vertical scale increases a single node’s resources while retaining simpler local state.',cs:'Distributed systems replace local memory and single-host ordering with network protocols, retries and partial failure.',location:'Current queue, rate limits and SQLite are process/local. docs/OPERATIONS.md captures single-node deployment constraints.',snippet:'Current: one VM → one bot process → external APIs',why:'Plan credible evolution from measured queue and resource limits.',without:'Multiplying traffic alone does not say whether CPU, RAM, disk, source APIs or Telegram will fail first.',alternatives:'Increase VM; tune bounded concurrency; add worker process; durable queue; shared DB/storage; multiple nodes.',choice:'Measure queue wait and resource saturation at every stage; choose the smallest move. **[E]** 10×/100×/1,000× exercises use user-supplied assumptions, not production forecast.',interview:'“I would not pick a distributed queue from a traffic multiplier. I would find which service objective fails, identify the saturated resource, and evolve only the affected boundary while defining durability and duplicate-work semantics.”',followup:'Why can a 100× system still fit on one node, and why might 10× require distributed work?',resource:'all; new coordination/network at horizontal scale',protection:'capacity signals, admission control, reversible growth path',failure:'shared local state, disk ownership, duplicate jobs and correlated host failure',scale:'Add multiple nodes only when an adequate single node cannot meet measured availability or throughput needs.'},
  {id:'distributed-systems',title:'Distributed systems & partial failure',level:22,group:'Distributed systems',summary:'Multiple workers introduce coordination and failure modes absent from one-process memory.',intuition:'Two workshops cannot share a whiteboard unless they communicate; messages can be delayed or lost.',technical:'Distributed work scheduling needs ownership/leases, durable state, deduplication, shared storage, cross-node rate limits and behavior under network partitions.',cs:'This is networking plus concurrency and database consistency. A local mutex cannot coordinate two machines.',location:'Not implemented in the current project. Current queue, caches and rate limits are in process; SQLite lives on one host.',snippet:'Future only: ingress → durable queue → workers → shared DB/object storage',why:'Needed only if availability, throughput or durable recovery requires multiple workers.',without:'Two bot processes with local state can duplicate polling/work, bypass aggregate rate limits, and race on job/storage ownership.',alternatives:'Single adequate node; active-passive failover; partitioned workers; managed queue and shared database.',choice:'Defer distribution until a requirement justifies the cost. The current service avoids network coordination by design.',interview:'“Multiple workers introduce partial failure, duplicate delivery, leases, shared-state consistency and idempotency requirements. I would only distribute once one appropriately sized node cannot satisfy measured throughput or availability objectives.”',followup:'How would a worker lease expire safely if the worker is paused but not dead?',resource:'network, database, queue, object storage and ops',protection:'durable state, leases, idempotency keys, reconciliation',failure:'partition, duplicate execution, stale ownership, retry storms',scale:'Start with a documented requirement; do not treat a queue product as the architecture.'},
  {id:'technology-judgment',title:'Why not Redis, Celery or Kubernetes?',level:23,group:'Design judgment',summary:'A technology is justified by a problem it solves and a measurable trigger.',intuition:'Do not buy a forklift because it is impressive; ask if the boxes are too heavy for your current workflow.',technical:'Redis is an in-memory data store/broker; Celery/RQ/Arq provide task-queue abstractions; Kafka is a durable distributed log; Kubernetes orchestrates containers. None removes the need to define job durability, idempotency or capacity.',cs:'Each adds network services, deployment, failure domains and operational knowledge beyond its core algorithm.',location:'None is required by current v1. Production is systemd + local SQLite/in-memory queue + Docker sidecars.',snippet:'“What problem do we have, and what metric says this tool solves it?”',why:'Avoid resume-driven complexity and new failure modes.',without:'No immediate behavior fails from omitting them at measured workload; adopting them creates more state and operations.',alternatives:'A larger VM, current fair queue, SQLite, bounded threads, deliberate rejection/backpressure.',choice:'Keep the single-node design while it satisfies actual needs. **[M]** the completed measurement did not show sustained bot CPU throttling or prove user-job latency need for a new worker architecture.',interview:'“Redis/Celery would become reasonable if we needed durable cross-process scheduling, retries and worker distribution that our local queue could not provide. Kubernetes solves orchestration across a fleet; it is not a generic throughput switch.”',followup:'What consistency and recovery contract would you write before adopting a task broker?',resource:'RAM, network, operations, recovery burden',protection:'measure need; explicit trigger and rollback',failure:'new dependency outage, duplicate deliveries, stale queue, deployment overhead',scale:'Reconsider one technology at a time when its exact problem is measured.'},
  {id:'portfolio-story',title:'Explain the system honestly',level:20,group:'Interview practice',summary:'A strong project story connects constraint, diagnosis, change, evidence and limitation.',intuition:'Tell a clear engineering story, not a list of tools.',technical:'A concise technical narrative describes requirements, architecture, key decisions, validation and what remains unproven.',cs:'Translate implementation details into OS/network/database consequences and user impact.',location:'Code at v1.0.0 / 830f351; the 374acfd documentation commit describes that baseline without changing the application.',snippet:'Problem → evidence → smallest change → tests → production verification → caveat',why:'Interviewers need to assess judgment, not the number of technologies named.',without:'Overclaiming causality or scale undermines credibility.',alternatives:'30-second, 2-minute, 5-minute, 15-minute explanations for recruiter, SDE, SRE and system design audiences.',choice:'State exact measured evidence, code-derived facts and unknowns separately. Never imply large traffic where none was measured.',interview:'“I built a single-node Telegram media downloader. I bounded download and upload work, coalesced duplicate metadata extraction, and streamed media from disk to avoid full-file Python buffering. I validated behavior with regression tests and a 24-hour infrastructure comparison, but changing CPU steal and a small user-job sample limit causal claims.”',followup:'Which one change had the clearest direct correctness test, and which performance conclusion remains uncertain?',resource:'credibility and evidence quality',protection:'[M]/[C]/[E]/[R] labels; test and production verification',failure:'buzzword-heavy answers exaggerate scale or causal impact.',scale:'Adjust depth and audience; keep factual core unchanged.'}
];

